create index idx_ict_notif_followup on gov_repo.ict_incident_notifications(followup_deadline) where requires_followup=true and followup_completed_at is null;
create trigger trg_ict_notif_updated_at before update on gov_repo.ict_incident_notifications for each row execute function gov_repo.set_updated_at();
alter table gov_repo.ict_incident_notifications enable row level security;
create policy "Service role full access ict_incident_notifications" on gov_repo.ict_incident_notifications for all to service_role using(true) with check(true);
create policy "Org-scoped read ict_incident_notifications" on gov_repo.ict_incident_notifications for select to authenticated using(organisation_id=(select organisation_id from gov_repo.governance_users where email=auth.email() limit 1));
create table gov_repo.ict_incident_affected_services(service_id uuid primary key default uuid_generate_v4(),incident_id uuid not null references gov_repo.ict_incidents(incident_id) on delete cascade,service_name varchar(255) not null,service_ref varchar(100),ict_function_type gov_repo.ict_function_type not null,ai_system_id uuid references gov_repo.ai_systems(system_id),agent_id uuid references gov_repo.agents(agent_id),provider_id uuid references gov_repo.third_party_providers(provider_id),impact_started_at timestamptz not null,impact_ended_at timestamptz,downtime_minutes integer generated always as(case when impact_ended_at is not null then extract(epoch from(impact_ended_at-impact_started_at))::integer/60 else null end) stored,service_impact varchar(30) not null default 'degraded' check(service_impact in ('full_outage','degraded','data_loss','data_corruption','security_breach','performance','monitoring_only')),rto_target_minutes integer,rto_actual_minutes integer generated always as(case when impact_ended_at is not null then extract(epoch from(impact_ended_at-impact_started_at))::integer/60 else null end) stored,rto_breach boolean generated always as(case when rto_target_minutes is not null and impact_ended_at is not null then (extract(epoch from(impact_ended_at-impact_started_at))/60)>rto_target_minutes else false end) stored,clients_affected integer,impact_notes text,recovery_actions text,organisation_id uuid not null references gov_repo.organisations(organisation_id),created_at timestamptz not null default now());
create index idx_ict_services_incident on gov_repo.ict_incident_affected_services(incident_id);create index idx_ict_services_org on gov_repo.ict_incident_affected_services(organisation_id);create index idx_ict_services_ai_system on gov_repo.ict_incident_affected_services(ai_system_id) where ai_system_id is not null;create index idx_ict_services_agent on gov_repo.ict_incident_affected_services(agent_id) where agent_id is not null;create index idx_ict_services_rto_breach on gov_repo.ict_incident_affected_services(incident_id) where rto_breach=true;create index idx_ict_services_ict_function on gov_repo.ict_incident_affected_services(ict_function_type) where ict_function_type in ('critical','important');alter table gov_repo.ict_incident_affected_services enable row level security;create policy "Service role full access ict_incident_affected_services" on gov_repo.ict_incident_affected_services for all to service_role using(true) with check(true);create policy "Org-scoped read ict_incident_affected_services" on gov_repo.ict_incident_affected_services for select to authenticated using(organisation_id=(select organisation_id from gov_repo.governance_users where email=auth.email() limit 1));
alter table gov_repo.ict_incidents add constraint ict_major_requires_rationale check(not is_major_incident or major_classification_rationale is not null);alter table gov_repo.ict_incidents add constraint ict_resolved_has_timestamp check(status not in ('resolved','closed') or resolved_at is not null);alter table gov_repo.ict_incidents add constraint ict_closed_requires_rationale check(status!='closed' or(closed_at is not null and closure_rationale is not null));alter table gov_repo.ict_incidents add constraint ict_dora_deadlines_require_major check(initial_notification_deadline is null or is_major_incident=true);alter table gov_repo.ict_incidents add constraint ict_rca_completion_consistent check((rca_started_at is null)=(rca_conducted_by is null));alter table gov_repo.ict_incidents add constraint ict_detection_before_report check(detected_at is null or reported_at is null or detected_at<=reported_at);alter table gov_repo.ict_incidents add constraint ict_occurrence_before_detection check(occurred_at is null or detected_at is null or occurred_at<=detected_at);alter table gov_repo.ict_incidents add constraint ict_gdpr_deadline_when_pii check(not pii_data_exposed or dpa_notification_deadline is not null);
create index idx_ict_inc_severity on gov_repo.ict_incidents(severity);create index idx_ict_inc_status on gov_repo.ict_incidents(status);create index idx_ict_inc_category on gov_repo.ict_incidents(incident_category);create index idx_ict_inc_major on gov_repo.ict_incidents(organisation_id) where is_major_incident=true;create index idx_ict_inc_reporting_phase on gov_repo.ict_incidents(reporting_phase) where reporting_phase not in ('not_required','all_complete');create index idx_ict_inc_initial_notif_deadline on gov_repo.ict_incidents(initial_notification_deadline) where is_major_incident=true and initial_notification_sent_at is null;create index idx_ict_inc_intermediate_deadline on gov_repo.ict_incidents(intermediate_report_deadline) where is_major_incident=true and intermediate_report_sent_at is null;create index idx_ict_inc_final_deadline on gov_repo.ict_incidents(final_report_deadline) where is_major_incident=true and final_report_sent_at is null;create index idx_ict_inc_recovery_status on gov_repo.ict_incidents(recovery_status) where recovery_status not in ('closed');create index idx_ict_inc_rto_breach on gov_repo.ict_incidents(organisation_id) where rto_breach=true;create index idx_ict_inc_ai_system on gov_repo.ict_incidents(primary_ai_system_id) where primary_ai_system_id is not null;create index idx_ict_inc_ai_flag on gov_repo.ict_incidents(organisation_id) where involves_ai_system=true;create index idx_ict_inc_provider on gov_repo.ict_incidents(primary_provider_id) where primary_provider_id is not null;create index idx_ict_inc_third_party on gov_repo.ict_incidents(organisation_id) where involves_third_party=true;create index idx_ict_inc_pii on gov_repo.ict_incidents(organisation_id) where pii_data_exposed=true;create index idx_ict_inc_gdpr_deadline on gov_repo.ict_incidents(dpa_notification_deadline) where pii_data_exposed=true and gdpr_breach_notified=false;create index idx_ict_inc_occurred_at on gov_repo.ict_incidents(occurred_at desc) where occurred_at is not null;create index idx_ict_inc_detected_at on gov_repo.ict_incidents(detected_at desc) where detected_at is not null;create index idx_ict_inc_commander on gov_repo.ict_incidents(incident_commander_id) where incident_commander_id is not null;create index idx_ict_inc_impacted_systems on gov_repo.ict_incidents using gin(impacted_system_ids);create index idx_ict_inc_impacted_agents on gov_repo.ict_incidents using gin(impacted_agent_ids);create index idx_ict_inc_impacted_providers on gov_repo.ict_incidents using gin(impacted_provider_ids);create index idx_ict_inc_control_failures on gov_repo.ict_incidents using gin(control_failures);create index idx_ict_inc_tags on gov_repo.ict_incidents using gin(tags);;
